      <div class="hud" id="hudR"><svg id="arrow" width="46" height="46" viewBox="-23 -23 46 46"><g id="ag"><path d="M-16 0H12M12 0L4 -7M12 0L4 7" stroke="#fff" stroke-width="3" fill="none" stroke-linecap="round"/></g></svg><div class="dim" id="wtxt"></div></div>
